#include <stdio.h>



int main(void)
{
    int a[1][2] = {{2, 3}};
    int b[2][1] = {{4}, {5}};
    int sum = 0;
    for (int k = 0; k < 2; k++) {
        sum += a[0][k] * b[k][0];
    }
    printf("%d\n", sum);
    return 0;
}

